package com.example.smartexpenseanalyzer.config;
import com.example.smartexpenseanalyzer.model.AppUser; import com.example.smartexpenseanalyzer.repository.AppUserRepository; import com.example.smartexpenseanalyzer.service.AdminProfileService; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner admin(AppUserRepository repo,PasswordEncoder enc,AdminProfileService admins){return args->{String email=System.getenv().getOrDefault("ADMIN_EMAIL","");String pass=System.getenv().getOrDefault("ADMIN_PASSWORD","");if(!email.isBlank()&&pass.length()>=12){AppUser u=repo.findByEmailIgnoreCase(email).orElse(null);if(u==null){u=new AppUser();u.name="Administrator";u.email=email.toLowerCase();u.passwordHash=enc.encode(pass);u.role="ADMIN";u=repo.save(u);}if(u.role.equals("ADMIN"))admins.ensureProfile(u);}};} }
